# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MODERN PERİYODİK SİSTEM: PERİYOTLAR, GRUPLAR VE BLOKLAR</text>\n  <rect x="25" y="42" width="320" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="185" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">MODERN PERİYODİK TABLONUN YAPISI</text>\n  <text x="38" y="90" font-size="11.5" fill="#1e3a8a">• Henry Moseley: Elementleri artan ATOM NUMARASINA</text>\n  <text x="48" y="106" font-size="11" font-weight="bold" fill="#1d4ed8">(proton sayısına) göre sıralamıştır.</text>\n  <text x="38" y="128" font-size="11.5" fill="#1e3a8a">• 7 Yatay Sıra → PERİYOT (En büyük baş kuantum sayısı n)</text>\n  <text x="38" y="150" font-size="11.5" fill="#1e3a8a">• 18 Düşey Sütun → GRUP (IUPAC: 1-18; A ve B grupları)</text>\n  <text x="48" y="168" font-size="11" fill="#1e3a8a">- 8 tane A grubu (Baş grup): s ve p bloğu elementleri</text>\n  <text x="48" y="184" font-size="11" fill="#1e3a8a">- 8 tane B grubu (Yan grup / 10 sütun): d ve f bloğu</text>\n  <rect x="38" y="196" width="294" height="34" rx="6" fill="#dbeafe"/>\n  <text x="185" y="217" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Aynı gruptaki elementlerin kimyasal özellikleri benzerdir.</text>\n  <rect x="360" y="42" width="315" height="200" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">PERİYODİK TABLODA BLOKLAR (s, p, d, f)</text>\n  <rect x="380" y="84" width="48" height="95" rx="4" fill="#bfdbfe" stroke="#2563eb" stroke-width="1.5"/>\n  <text x="404" y="135" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">s</text>\n  <text x="404" y="152" text-anchor="middle" font-size="9.5" fill="#1e3a8a">1A-2A</text>\n  <rect x="434" y="114" width="110" height="65" rx="4" fill="#bbf7d0" stroke="#16a34a" stroke-width="1.5"/>\n  <text x="489" y="146" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">d bloğu</text>\n  <text x="489" y="162" text-anchor="middle" font-size="9.5" fill="#14532d">B Grupları (3-12)</text>\n  <rect x="550" y="84" width="105" height="95" rx="4" fill="#fde68a" stroke="#d97706" stroke-width="1.5"/>\n  <text x="602" y="135" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">p bloğu</text>\n  <text x="602" y="152" text-anchor="middle" font-size="9.5" fill="#78350f">3A - 8A (13-18)</text>\n  <rect x="415" y="190" width="195" height="36" rx="4" fill="#f3e8ff" stroke="#9333ea" stroke-width="1.5"/>\n  <text x="512" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">f bloğu (Lantanitler &amp; Aktinitler - 3B)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ELEKTRON DİZİLİMİ İLE PERİYOT VE GRUP BULMA KURALLARI</text>\n  <rect x="25" y="42" width="320" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="185" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">BAŞ GRUP (A GRUBU: s ve p BLOĞU)</text>\n  <text x="38" y="92" font-size="11.5" font-weight="bold" fill="#14532d">• Periyot No = En büyük baş kuantum sayısı (n_max)</text>\n  <text x="38" y="114" font-size="11.5" font-weight="bold" fill="#14532d">• Grup No = Değerlik elektron sayısı (s veya s+p)</text>\n  <text x="45" y="138" font-size="11" fill="#15803d">- ₁₁Na: 1s² 2s² 2p⁶ 3s¹ → 3. Periyot, 1A (1. grup), s bloğu</text>\n  <text x="45" y="158" font-size="11" fill="#15803d">- ₁₇Cl: 1s² 2s² 2p⁶ 3s² 3p⁵ → 3. Periyot, 7A (17. grup), p bloğu</text>\n  <text x="45" y="178" font-size="11" fill="#15803d">- ₃₃As: [Ar] 4s² 3d¹⁰ 4p³ → 4. Periyot, 5A (15. grup), p bloğu</text>\n  <rect x="38" y="192" width="294" height="38" rx="6" fill="#dcfce7" stroke="#22c55e"/>\n  <text x="185" y="215" text-anchor="middle" font-size="11" font-weight="bold" fill="#991b1b">İstisna: ₂He: 1s² → Değerlik e⁻ = 2 olmasına rağmen 8A (18. grup)!</text>\n  <rect x="360" y="42" width="315" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">GEÇİŞ METALLERİ (B GRUBU: d BLOĞU)</text>\n  <text x="374" y="92" font-size="11.5" font-weight="bold" fill="#581c87">• Dizilimi (n-1)d ile bitenler B grubundadır (4. periyottan başlar).</text>\n  <text x="374" y="114" font-size="11.5" font-weight="bold" fill="#581c87">• ns ve (n-1)d elektronları toplamı (s + d):</text>\n  <text x="382" y="135" font-size="11" fill="#6b21a8">- Toplam 3, 4, 5, 6, 7 ise → 3B, 4B, 5B, 6B, 7B</text>\n  <text x="382" y="155" font-size="11" font-weight="bold" fill="#7e22ce">- Toplam 8, 9 veya 10 ise → tamamı 8B grubu (8, 9, 10. grup)</text>\n  <text x="382" y="175" font-size="11" fill="#6b21a8">- Toplam 11 ise (s¹d¹⁰) → 1B (11. grup, örn: ₂₉Cu)</text>\n  <text x="382" y="195" font-size="11" fill="#6b21a8">- Toplam 12 ise (s²d¹⁰) → 2B (12. grup, örn: ₃₀Zn)</text>\n  <text x="374" y="220" font-size="11" font-weight="bold" fill="#581c87">Örnek: ₂₆Fe: [Ar] 4s² 3d⁶ → 4. Periyot, 8B (IUPAC 8. Grup)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ÖZEL GRUP ADLARI VE ELEMENT SINIFLARI</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9a3412">BAŞLICA GRUPLARIN ÖZEL ADLARI</text>\n  <text x="40" y="92" font-size="11.5" fill="#7c2d12">• 1A (1. Grup): Alkali Metaller (₁H hariç! H ametaldir)</text>\n  <text x="40" y="114" font-size="11.5" fill="#7c2d12">• 2A (2. Grup): Toprak Alkali Metaller (tamamı metal)</text>\n  <text x="40" y="136" font-size="11.5" fill="#7c2d12">• 3A (13. Grup): Toprak Metalleri (₅B yarı metal, diğerleri metal)</text>\n  <text x="40" y="158" font-size="11.5" fill="#7c2d12">• 6A (16. Grup): Kalkojenler (Oksijen grubu)</text>\n  <text x="40" y="180" font-size="11.5" fill="#7c2d12">• 7A (17. Grup): Halojenler (Tuz yapıcı reaktif ametaller)</text>\n  <text x="40" y="202" font-size="11.5" fill="#7c2d12">• 8A (18. Grup): Soy Gazlar / Asal Gazlar (He, Ne, Ar...)</text>\n  <text x="40" y="224" font-size="11.5" fill="#7c2d12">• B Grupları: Geçiş Metalleri (f bloğu: İç Geçiş Metalleri)</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">ELEMENT SINIFLARININ ÖZELLİKLERİ</text>\n  <text x="370" y="90" font-size="11.5" font-weight="bold" fill="#164e63">• Metaller:</text>\n  <text x="378" y="106" font-size="10.5" fill="#155e75">Isı ve elektriği iyi iletir, tel-levha olur (işlenebilir), bileşiklerinde</text>\n  <text x="378" y="120" font-size="10.5" fill="#155e75">daima pozitif (+) yük (katyon) alır, cıva (Hg) hariç oda koşullarında katıdır.</text>\n  <text x="370" y="142" font-size="11.5" font-weight="bold" fill="#164e63">• Ametaller (H, C, N, O, F, P, S, Cl, Br, I, Se):</text>\n  <text x="378" y="158" font-size="10.5" fill="#155e75">Mat görünümlüdür, kırılgan olduklarından işlenemez, hem (+) hem (-)</text>\n  <text x="378" y="172" font-size="10.5" fill="#155e75">değerlik alabilir (F yalnız -1 alır).</text>\n  <text x="370" y="194" font-size="11.5" font-weight="bold" fill="#164e63">• Yarı Metaller (B, Si, Ge, As, Sb, Te...) &amp; Soy Gazlar:</text>\n  <text x="378" y="210" font-size="10.5" fill="#155e75">Yarı metaller fiziksel olarak metale, kimyasal olarak ametale benzer.</text>\n  <text x="378" y="224" font-size="10.5" fill="#155e75">Soy gazlar tek atomlu gazdır, kararlıdır, bileşik oluşturmaya yatkın değildir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
